#include "account_analysis.hpp"
#include <QCoreApplication>
#include <iostream>
void need(bool b,const char* why){if(!b)throw std::runtime_error(why);}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{QJsonObject account{{"id","a"}},buy{{"id","b"},{"accountId","a"},{"instrumentId","SH:stock:600001"},{"date","2026-10-01"},{"side","buy"},{"quantity",100},{"price",10.},{"fee",5.},{"tax",0.}};auto sell=buy;sell["id"]="s";sell["date"]="2026-10-02";sell["side"]="sell";sell["quantity"]=40;sell["price"]=12.;sell["fee"]=1.;sell["tax"]=1.;QJsonArray trades{buy,sell};QJsonObject quote{{"SH:stock:600001",QJsonObject{{"price",11.},{"tradeDate","2026-10-12"},{"source","input"}}}};QJsonObject raw{{"snapshot_date","2026-10-01"},{"cash_balance",1000.},{"total_market_value",2000.},{"total_assets",3000.},{"total_pnl",100.}};QJsonObject report{{"id","h"},{"accountId","a"},{"legacySource","portfolio_snapshots"},{"legacyOriginal",raw}};auto p=accountAnalysis::evaluate(account,trades,quote,QJsonArray{report});need(p["cashBalance"].isNull()&&p["totalAssets"].isNull(),"missing cash replaced zero");need(p["realized"].toDouble()==76&&p["unrealized"].toDouble()==57,"moving average pnl");need(p["recordedCashFlow"].toDouble()==-527,"old amount fee semantics");account["cashBalance"]=0.;p=accountAnalysis::evaluate(account,trades,quote,QJsonArray{report});need(p["totalAssets"].toDouble()==660,"explicit zero cash");auto history=p["history"];quote["SH:stock:600001"]=QJsonObject{{"price",99.}};need(accountAnalysis::evaluate(account,trades,quote,QJsonArray{report})["history"]==history,"future quote backfilled history");need(p["performanceReturn"].isNull(),"invented performance return");auto other=report;other["accountId"]="other";need(accountAnalysis::evaluate(account,trades,quote,QJsonArray{other})["history"].toArray().isEmpty(),"history account isolation");buy.remove("fee");need(accountAnalysis::evaluate(account,QJsonArray{buy},quote,{})["recordedCashFlow"].isNull(),"missing fee zero cash flow");std::cout<<"account analysis: cash unknown/zero, average-cost contributions, fee cash flow, immutable history and account identity GREEN\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}return 0;}
